window.futvizVista("eficiencia-definicion","<div class=\"rx-mount\" data-rx=\"scatter\" data-rx-id=\"eficiencia-definicion\" style=\"min-height:520px\"></div><script>(window.futvizVistas=window.futvizVistas||{})[\"eficiencia-definicion\"]={\"id\":\"eficiencia-definicion\",\"titulo\":\"Eficiencia de definici\u00f3n\",\"tabla\":\"equipos\",\"entidad\":\"equipos\",\"x\":{\"col\":\"sh_Standard_SoT%\",\"label\":\"Precisi\u00f3n \u2014 % de tiros que van a puerta (SoT%)\",\"corto\":\"Precisi\u00f3n\",\"dec\":1},\"y\":{\"col\":\"sh_Standard_G/SoT\",\"label\":\"Definici\u00f3n \u2014 goles por tiro a puerta (G/SoT)\",\"corto\":\"Definici\u00f3n\",\"dec\":2},\"referencia\":{\"tipo\":\"promedios\",\"cuadrantes\":{\"tr\":\"certeros y letales\",\"tl\":\"poco a puerta, pero letales\",\"br\":\"mucho a puerta, poca pegada\",\"bl\":\"ni certeros ni letales\"}},\"requiere\":[\"sh_Standard_SoT%\",\"sh_Standard_G/SoT\"],\"subtitulo\":\"Precisi\u00f3n (llegar a puerta) vs. definici\u00f3n (marcar una vez ah\u00ed) \u00b7 {temporada}\",\"filtros\":{\"nivel\":true},\"metricas\":[{\"id\":\"dist\",\"etiqueta\":\"Alejados\",\"ayuda\":\"Los que m\u00e1s se alejan del centro de la nube (en desviaciones est\u00e1ndar)\"},{\"id\":\"x\",\"etiqueta\":\"Precisi\u00f3n\",\"ayuda\":\"Los de mayor Precisi\u00f3n \u2014 % de tiros que van a puerta (SoT%)\"},{\"id\":\"y\",\"etiqueta\":\"Definici\u00f3n\",\"ayuda\":\"Los de mayor Definici\u00f3n \u2014 goles por tiro a puerta (G/SoT)\"}],\"queMirar\":\"Cada punto es un equipo. El eje horizontal es **llegar** (qu\u00e9 porcentaje de sus tiros van a puerta) y el vertical es **definir** (cu\u00e1ntos goles saca de cada tiro a puerta). Arriba a la derecha est\u00e1n los que hacen bien las dos cosas; abajo a la derecha, los que tiran mucho a puerta y no la meten.\",\"porQue\":\"Las dos van en ejes separados porque **no son la misma habilidad**: correlacionan 0.25 sobre las 580 observaciones, o sea que comparten apenas un 6% de su variaci\u00f3n. Un equipo puede ser muy bueno generando remates claros y flojo remat\u00e1ndolos, y al rev\u00e9s. Si se mezclaran en un solo indicador de \\\"eficiencia\\\" esa distinci\u00f3n se perder\u00eda, que es justo lo que el gr\u00e1fico quiere mostrar.\",\"insight\":\"definicion\",\"fuente\":\"FBref\",\"colorPor\":[\"liga\"]};</script>");